content.text:
{
  "name": "Logix 可编程逻辑控制器（PLC）",
  "name_en": "Logix Programmable Logic Controller (PLC)",
  "manufacturer": "Rockwell Automation",
  "description": "一种支持 EtherNet/IP 与 CIP 通信的工业可编程逻辑控制器，用于实验装置、自动化测试台或工艺系统中的顺序控制、联锁控制以及 I/O 数据交换。",
  "description_en": "An industrial programmable logic controller that supports EtherNet/IP and CIP communication, used in laboratory rigs, automation test stands, and process systems for sequence control, interlocks, and I/O data exchange.",
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接到 PLC。",
      "description_en": "Connect to the PLC."
    },
    {
      "action_name": "auto-send",
      "description": "向 PLC 发送通信请求并获取返回的数据与状态。",
      "description_en": "Send a communication request to the PLC and obtain the returned data and status."
    },
    {
      "action_name": "auto-listen",
      "description": "监听来自 PLC 的 CIP 数据表写入消息。",
      "description_en": "Listen for CIP data table write messages from the PLC."
    },
    {
      "action_name": "auto-close",
      "description": "关闭与 PLC 的连接。",
      "description_en": "Close the connection to the PLC."
    },
    {
      "action_name": "auto-receive_data",
      "description": "接收来自 PLC 的网络数据。",
      "description_en": "Receive network data from the PLC."
    },
    {
      "action_name": "auto-discover",
      "description": "在网络上发现可用的 PLC 设备。",
      "description_en": "Discover available PLC devices on the network."
    }
  ],
  "tag_hints": [
    "PLC control",
    "EtherNet/IP",
    "CIP protocol",
    "Allen-Bradley Logix",
    "industrial automation",
    "network device discovery"
  ]
}

